ALTER TABLE "app_settings"
ADD COLUMN "research_instructions" TEXT NOT NULL DEFAULT 'Evaluate whether this business is a strong web-development prospect. Prioritize concrete website problems that create business friction, weak credibility, poor conversion paths, weak local-search foundations, or wasted paid-traffic opportunity. Prefer problems that can support a specific outreach angle. Disqualify businesses that are clearly a poor fit or have no meaningful web opportunity.',
ADD COLUMN "outreach_instructions" TEXT NOT NULL DEFAULT 'Write a concise personalized cold email in plain business language. Focus on one specific problem and why it matters to the business. Do not dump an audit or use technical jargon. Avoid generic compliments, fake familiarity, hype, and placeholders. Use a low-friction call to action aimed at starting a conversation or booking a consultation.';
